import React, { useState } from "react";
import { Link } from "react-router-dom";
import { Menu, X } from "lucide-react"; // hamburger & close icons

export default function Navbar() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <nav className="bg-blue-600 text-white px-6 py-3 shadow-md">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold tracking-wide">AI Interview Coach</h1>

        {/* Desktop Menu */}
        <div className="hidden md:flex space-x-6">
          <Link to="/" className="hover:text-gray-200 transition">Home</Link>
          <Link to="/interview" className="hover:text-gray-200 transition">Interview</Link>
          <Link to="/feedback" className="hover:text-gray-200 transition">Feedback</Link>
        </div>

        {/* Mobile Menu Button */}
        <button
          className="md:hidden"
          onClick={() => setIsOpen(!isOpen)}
        >
          {isOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      {/* Mobile Dropdown Menu */}
      {isOpen && (
        <div className="md:hidden mt-3 space-y-2">
          <Link
            to="/"
            onClick={() => setIsOpen(false)}
            className="block hover:text-gray-200 transition"
          >
            Home
          </Link>
          <Link
            to="/interview"
            onClick={() => setIsOpen(false)}
            className="block hover:text-gray-200 transition"
          >
            Interview
          </Link>
          <Link
            to="/feedback"
            onClick={() => setIsOpen(false)}
            className="block hover:text-gray-200 transition"
          >
            Feedback
          </Link>
        </div>
      )}
    </nav>
  );
}
